#include "stdafx.h"#include "HcdDebugApp.h"#include "ListOfBlocksView.h"// KListOfBlocksViewIMPLEMENT_DYNCREATE(KListOfBlocksView, CListView)KListOfBlocksView::KListOfBlocksView(): m_pCtrl( NULL ), m_NotifiereSelectedBlock( NULL ){}KListOfBlocksView::~KListOfBlocksView(){}KHcdDebugDoc* KListOfBlocksView::GetDocument(){  ASSERT(m_pDocument->IsKindOf(RUNTIME_CLASS(KHcdDebugDoc)));  return (KHcdDebugDoc*)m_pDocument;}BEGIN_MESSAGE_MAP(KListOfBlocksView, CListView)  ON_MESSAGE( WM_USER, OnWmUser)    ON_NOTIFY_REFLECT(LVN_ITEMCHANGED, &KListOfBlocksView::OnLvnItemchanged)END_MESSAGE_MAP()// KListOfBlocksView diagnostics#ifdef _DEBUGvoid KListOfBlocksView::AssertValid() const{	CListView::AssertValid();}#ifndef _WIN32_WCEvoid KListOfBlocksView::Dump(CDumpContext& dc) const{	CListView::Dump(dc);}#endif#endif //_DEBUG// KListOfBlocksView message handlersBOOL KListOfBlocksView::Create(LPCTSTR lpszClassName, LPCTSTR lpszWindowName, DWORD dwStyle, const RECT& rect, CWnd* pParentWnd, UINT nID, CCreateContext* pContext){  dwStyle |= LVS_REPORT | LVS_SINGLESEL | LVS_SHOWSELALWAYS | LVS_ALIGNLEFT | LVS_NOSORTHEADER;  BOOL r = CListView::Create(lpszClassName, lpszWindowName, dwStyle, rect, pParentWnd, nID, pContext);  m_pCtrl = &GetListCtrl();  m_pCtrl->InsertColumn ( 0, "", LVCFMT_LEFT, rect.right/2, 0 );  m_pCtrl->InsertColumn ( 1, "", LVCFMT_LEFT, rect.right/2-5, 0 );  m_pCtrl->SetExtendedStyle ( LVS_EX_FULLROWSELECT|LVS_EX_GRIDLINES );  return r;}LRESULT KListOfBlocksView::OnWmUser( WPARAM wParam, LPARAM lParam ){  if( !(!wParam && 77==lParam) )    return 0L;  KHcdDebugDoc *pDoc = GetDocument();  INotifier* pN = pDoc->GetEventNotifier( eSelectedPage );  m_connections.push_back( ConnectNotifierA( pN, this, &KListOfBlocksView::OnSelectedPage ) );  m_NotifiereSelectedBlock = pDoc->GetEventNotifier( eSelectedBlock );  return 1L;}void KListOfBlocksView::OnSelectedPage( IHcdDrawable *pDraw ){  m_pCtrl->DeleteAllItems();  size_t c = pDraw->GetLogixBlocks( NULL, 0 );  if( !c )    return;  std::vector<IHcdElement*> buf;  buf.resize( c );  c = pDraw->GetLogixBlocks( &buf.at(0), buf.size() );  int add = 0;  for( size_t i=0; i<c; ++i )  {    IHcdElement *pBlock = buf[i];    int a = m_pCtrl->InsertItem( add++, pBlock->szName );    m_pCtrl->SetItemText( a, 1, pBlock->m_pszType );    m_pCtrl->SetItemData( a, (DWORD_PTR)pBlock );  }}void KListOfBlocksView::OnLvnItemchanged(NMHDR *pNMHDR, LRESULT *pResult){  LPNMLISTVIEW pNMLV = reinterpret_cast<LPNMLISTVIEW>(pNMHDR);  // TODO: Add your control notification handler code here  if( pNMLV->uNewState==3 )  {    int nItem = pNMLV->iItem;    if( m_NotifiereSelectedBlock )    {      IHcdElement *pBlock = (IHcdElement*)m_pCtrl->GetItemData( pNMLV->iItem );      m_NotifiereSelectedBlock->DoNotify( eSelectedBlock, pBlock );    }  }  else if( pNMLV->uNewState==0 )    m_NotifiereSelectedBlock->DoNotify( eSelectedBlock, NULL );  *pResult = 0;}